package main

import (
	"crypto/sha256"
	"fmt"
	"io"
	"net"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/ochinchina/supervisord/config"
)

var configTemplate = strings.Join([]string{
	"; Supervisord: single binary + this configuration file.",
	"; Security credentials and TLS material are generated by supervisord init.",
	"[supervisord]", "logfile = %(here)s/supervisord.log", "logfile_maxbytes = 50MB", "logfile_backups = 5", "logfile_timestamp_suffix = false", "loglevel = info", "pidfile = %(here)s/supervisord.pid", "",
	"[inet_http_server]", "port = 0.0.0.0:8002", "", "[supervisorctl]", "serverurl = https://localhost:8002", "",
	"; Add programs here or use [include] files=conf.d/*.conf.",
	"; [program:my-app]", "; directory = %(here)s/apps/my-app", "; command = ./my-app --name \"hello world\"", "; autostart = true", "; autorestart = unexpected", "; stopsignal = TERM", "; stopwaitsecs = 10", "; stopasgroup = true", "; killasgroup = true", "; stdout_logfile = logs/stdout.log", "; stderr_logfile = logs/stderr.log", "; stdout_logfile_timestamp_suffix = false", "; stderr_logfile_timestamp_suffix = false", "; stdout_logfile_maxbytes = 50MB", "; stderr_logfile_maxbytes = 50MB", "; stdout_logfile_backups = 5", "; stderr_logfile_backups = 5", "",
}, "\n")

// InitTemplateCommand creates configuration and initializes secure access.
type InitTemplateCommand struct {
	OutFile          string "short:\"o\" long:\"output\" description:\"configuration path (default supervisord.conf)\""
	Reset            bool   "long:\"reset-password\" description:\"generate a new password and invalidate existing credentials\""
	RenewCertificate bool   "long:\"renew-certificate\" description:\"replace TLS material with a new self-signed certificate\""
	Port             string "long:\"port\" default:\"8002\" description:\"management port for new configuration\""
	Bind             string "long:\"bind\" default:\"0.0.0.0\" description:\"listen address for new configuration\""
}

var initTemplateCommand InitTemplateCommand

func (x *InitTemplateCommand) Execute(args []string) error {
	port, err := strconv.Atoi(x.Port)
	if err != nil || port < 1 || port > 65535 || strings.ContainsAny(x.Bind, "\r\n []") {
		return fmt.Errorf("invalid bind address or port (expected 1-65535)")
	}
	path := x.OutFile
	if path == "" {
		path = options.Configuration
	}
	if path == "" {
		path = "supervisord.conf"
	}
	absolute, err := filepath.Abs(path)
	if err != nil {
		return err
	}
	path = absolute
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err == nil {
		content := strings.Replace(configTemplate, "0.0.0.0:8002", net.JoinHostPort(x.Bind, x.Port), 1)
		content = strings.Replace(content, "https://localhost:8002", "https://localhost:"+x.Port, 1)
		_, writeErr := io.WriteString(file, content)
		closeErr := file.Close()
		if writeErr != nil {
			return writeErr
		}
		if closeErr != nil {
			return closeErr
		}
	} else if !os.IsExist(err) {
		return err
	}
	cfg := config.NewConfig(path)
	if _, err = cfg.Load(); err != nil {
		return err
	}
	auth, password, err := prepareWebSecurityOptions(cfg, x.Reset, x.RenewCertificate)
	if err != nil {
		return err
	}
	fingerprint := sha256.Sum256(auth.certificate.Certificate[0])
	fmt.Printf("Configuration: %s\nAdministrator: %s\n", path, auth.username)
	if password != "" {
		fmt.Printf("Initial password: %s\nSave this password; only its bcrypt hash is stored.\n", password)
	} else {
		fmt.Println("Existing password preserved. Use --reset-password only if you need a new password.")
	}
	entry, _ := cfg.GetInetHTTPServer()
	fmt.Printf("HTTPS listen address: %s\nCertificate SHA-256: %x\n", entry.GetString("port", ":8002"), fingerprint)
	return nil
}

// GenTemplate writes a configuration without fixed credentials.
func GenTemplate(writer io.Writer) error {
	_, err := io.WriteString(writer, configTemplate)
	return err
}
func init() {
	_, _ = parser.AddCommand("init", "initialize secure configuration", "Create a configuration, random credentials and a self-signed certificate; retain existing settings.", &initTemplateCommand)
}
